RF = {"DC1": 3, "DC2": 3}
def quorum(n): return n // 2 + 1
def ok(level, alive, local="DC1"):
    if level == "EACH_QUORUM":
        return all(alive[dc] >= quorum(RF[dc]) for dc in RF)
    if level == "LOCAL_QUORUM":
        return alive[local] >= quorum(RF[local])
    return sum(alive.values()) >= quorum(sum(RF.values()))  # QUORUM

for name, alive in [("정상", {"DC1": 3, "DC2": 3}), ("DC2 장애", {"DC1": 3, "DC2": 0})]:
    print(name, {lv: ok(lv, alive) for lv in ["EACH_QUORUM", "LOCAL_QUORUM", "QUORUM"]})
# 정상 {'EACH_QUORUM': True, 'LOCAL_QUORUM': True, 'QUORUM': True}
# DC2 장애 {'EACH_QUORUM': False, 'LOCAL_QUORUM': True, 'QUORUM': False}

limits = {"상담봇": 60_000, "코드리뷰": 20_000}
used = {"상담봇": 0, "코드리뷰": 0}
backends = [("사내-vLLM", False), ("클라우드-API", True)]  # (이름, 살아 있나)

def call(team, tokens):
    if used[team] + tokens > limits[team]:
        return "429 한도 초과"
    for name, up in backends:
        if up:
            used[team] += tokens
            return "200 via " + name
    return "503 모두 실패"

for team, tok in [("코드리뷰", 15_000), ("코드리뷰", 8_000), ("상담봇", 30_000)]:
    print(team, tok, "->", call(team, tok))
# 코드리뷰 15000 -> 200 via 클라우드-API
# 코드리뷰 8000 -> 429 한도 초과
# 상담봇 30000 -> 200 via 클라우드-API

now = 10_000
feats = {"최근1시간_앱실행": (3, now - 600), "30일_이체건수": (41, now - 86_400)}
sla = {"최근1시간_앱실행": 3_600, "30일_이체건수": 2 * 86_400}
for k, (v, ts) in feats.items():
    age = now - ts
    print(k, v, "나이", age, "초 ->", "사용" if age <= sla[k] else "다시 만들기")
# 최근1시간_앱실행 3 나이 600 초 -> 사용
# 30일_이체건수 41 나이 86400 초 -> 사용
